import React, { useMemo, useState } from 'react';
import type { Address, AddressErrors, CartItem } from './types';
import './Checkout.css';

interface CheckoutPageProps {
  items: CartItem[];
  onBack: () => void;
  onPay: (address: Address) => void | Promise<void>;
  shippingFee?: number;
}

const EMPTY_ADDRESS: Address = {
  fullName: '',
  street: '',
  city: '',
  postalCode: '',
  country: '',
  phone: '',
};

function formatPrice(value: number): string {
  return value.toLocaleString(undefined, {
    style: 'currency',
    currency: 'USD',
  });
}

function validate(address: Address): AddressErrors {
  const errors: AddressErrors = {};

  if (!address.fullName.trim()) errors.fullName = 'Full name is required';
  if (!address.street.trim()) errors.street = 'Street address is required';
  if (!address.city.trim()) errors.city = 'City is required';
  if (!address.postalCode.trim()) errors.postalCode = 'Postal code is required';
  if (!address.country.trim()) errors.country = 'Country is required';
  if (!address.phone.trim()) {
    errors.phone = 'Phone number is required';
  } else if (!/^[+\d][\d\s-]{6,}$/.test(address.phone.trim())) {
    errors.phone = 'Enter a valid phone number';
  }

  return errors;
}

export default function CheckoutPage({
  items,
  onBack,
  onPay,
  shippingFee = 5,
}: CheckoutPageProps) {
  const [address, setAddress] = useState<Address>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<AddressErrors>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [items]
  );
  const total = subtotal + (items.length > 0 ? shippingFee : 0);

  function handleChange(field: keyof Address, value: string) {
    setAddress((prev) => ({ ...prev, [field]: value }));
  }

  async function handlePay(event: React.FormEvent) {
    event.preventDefault();

    const validationErrors = validate(address);
    setErrors(validationErrors);
    if (Object.keys(validationErrors).length > 0 || items.length === 0) {
      return;
    }

    setIsSubmitting(true);
    try {
      await onPay(address);
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <div className="checkout-page">
      <button type="button" className="back-button" onClick={onBack}>
        &larr; Back to cart
      </button>

      <h1 className="checkout-title">Checkout</h1>

      <div className="checkout-layout">
        <section className="cart-section" aria-labelledby="cart-heading">
          <h2 id="cart-heading">Your items</h2>

          {items.length === 0 ? (
            <p className="empty-cart">Your cart is empty.</p>
          ) : (
            <ul className="cart-list">
              {items.map((item) => (
                <li key={item.id} className="cart-item">
                  {item.imageUrl && (
                    <img
                      className="cart-item-image"
                      src={item.imageUrl}
                      alt={item.name}
                    />
                  )}
                  <div className="cart-item-details">
                    <span className="cart-item-name">{item.name}</span>
                    <span className="cart-item-qty">Qty: {item.quantity}</span>
                  </div>
                  <span className="cart-item-price">
                    {formatPrice(item.price * item.quantity)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <div className="order-summary">
            <div className="order-summary-row">
              <span>Subtotal</span>
              <span>{formatPrice(subtotal)}</span>
            </div>
            <div className="order-summary-row">
              <span>Shipping</span>
              <span>{formatPrice(items.length > 0 ? shippingFee : 0)}</span>
            </div>
            <div className="order-summary-row order-summary-total">
              <span>Total</span>
              <span>{formatPrice(total)}</span>
            </div>
          </div>
        </section>

        <section className="address-section" aria-labelledby="address-heading">
          <h2 id="address-heading">Delivery address</h2>

          <form className="address-form" onSubmit={handlePay} noValidate>
            <div className="form-field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                value={address.fullName}
                onChange={(e) => handleChange('fullName', e.target.value)}
                aria-invalid={Boolean(errors.fullName)}
              />
              {errors.fullName && (
                <span className="field-error">{errors.fullName}</span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="street">Street address</label>
              <input
                id="street"
                type="text"
                value={address.street}
                onChange={(e) => handleChange('street', e.target.value)}
                aria-invalid={Boolean(errors.street)}
              />
              {errors.street && (
                <span className="field-error">{errors.street}</span>
              )}
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  value={address.city}
                  onChange={(e) => handleChange('city', e.target.value)}
                  aria-invalid={Boolean(errors.city)}
                />
                {errors.city && (
                  <span className="field-error">{errors.city}</span>
                )}
              </div>

              <div className="form-field">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  value={address.postalCode}
                  onChange={(e) => handleChange('postalCode', e.target.value)}
                  aria-invalid={Boolean(errors.postalCode)}
                />
                {errors.postalCode && (
                  <span className="field-error">{errors.postalCode}</span>
                )}
              </div>
            </div>

            <div className="form-field">
              <label htmlFor="country">Country</label>
              <input
                id="country"
                type="text"
                value={address.country}
                onChange={(e) => handleChange('country', e.target.value)}
                aria-invalid={Boolean(errors.country)}
              />
              {errors.country && (
                <span className="field-error">{errors.country}</span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="phone">Phone number</label>
              <input
                id="phone"
                type="tel"
                value={address.phone}
                onChange={(e) => handleChange('phone', e.target.value)}
                aria-invalid={Boolean(errors.phone)}
              />
              {errors.phone && (
                <span className="field-error">{errors.phone}</span>
              )}
            </div>

            <button
              type="submit"
              className="pay-button"
              disabled={isSubmitting || items.length === 0}
            >
              {isSubmitting ? 'Processing...' : `Pay ${formatPrice(total)}`}
            </button>
          </form>
        </section>
      </div>
    </div>
  );
}
```

